// Visual Elements: decorative art (botanicals, birds, figures, objects, watercolours) layered BEHIND the poem.
// Catalog + QC: elements-catalog.js (generated by scripts/build-motion-elements.mjs from the two supplied packs).
// Vector art is drawn from a pre-parsed path model with Canvas Path2D (no <img> of SVG, so nothing can taint the
// export canvas and tint works on every browser). Watercolours are same-origin WebP. Animation is a pure function of
// (element, time): the same state and time always paint the same pixels, in preview and in export.
import CATALOG from "./elements-catalog.js";

export const ELEMENTS = CATALOG.elements;
export const ELEMENT_QC = CATALOG.qc;
const BY_ID = new Map(ELEMENTS.map((e) => [e.id, e]));
export const elementById = (id) => BY_ID.get(id) || null;

export const CATEGORY_LABELS = {
  botanical: "Botanical",
  nature: "Nature",
  celestial: "Celestial",
  creatures: "Birds & creatures",
  ornaments: "Ornaments",
  couples: "Couples",
  solitude: "Solitude",
  literary: "Literary life",
  environments: "Places",
  objects: "Objects",
  watercolour: "Watercolour",
};
/** Only categories that actually contain approved elements (no empty chips). */
export const ELEMENT_CATEGORIES = Object.keys(CATEGORY_LABELS).filter((c) =>
  ELEMENTS.some((e) => e.category === c),
);
export const ELEMENT_STYLES = [
  ["line", "Line art"],
  ["silhouette", "Silhouette"],
  ["watercolour", "Watercolour"],
].filter(([k]) => ELEMENTS.some((e) => styleOf(e) === k));
export function styleOf(e) {
  return e.kind === "raster"
    ? "watercolour"
    : e.style === "silhouette"
      ? "silhouette"
      : "line";
}

export function searchElements({ q = "", category = "", style = "" } = {}) {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  return ELEMENTS.filter(
    (e) =>
      (!category || e.category === category) &&
      (!style || styleOf(e) === style) &&
      words.every((w) =>
        `${e.name} ${e.id} ${e.category} ${CATEGORY_LABELS[e.category] || ""} ${e.placement}`
          .toLowerCase()
          .includes(w),
      ),
  );
}

// ---------------------------------------------------------------- the composition's `elements` array
export const MAX_ELEMENTS = 24;
export const ELEMENT_ANIMS = ["none", "drift", "float", "sway", "fade", "draw"];
export const ANIM_LABELS = {
  none: "Still",
  drift: "Drift",
  float: "Float",
  sway: "Sway",
  fade: "Fade in",
  draw: "Draw on",
};
export const SIZE_MIN = 0.05,
  SIZE_MAX = 1.2;
const hex = (v) =>
  typeof v === "string" && /^#[0-9a-fA-F]{6}$/.test(v) ? v.toLowerCase() : null;
const num = (v, lo, hi, d) =>
  Number.isFinite(Number(v)) ? Math.min(hi, Math.max(lo, Number(v))) : d;
const r3 = (v) => Math.round(v * 1000) / 1000;

/** One element; x/y are the CENTRE as a fraction of the frame, size is the width as a fraction of the frame width. */
export function normalizeElement(e, i = 0) {
  const a = elementById(e?.asset);
  if (!a) return null;
  const an = e.anim || {};
  return {
    id:
      typeof e.id === "string" && /^[\w-]{1,24}$/.test(e.id) ? e.id : `el${i}`,
    asset: a.id,
    x: r3(num(e.x, -0.25, 1.25, 0.5)),
    y: r3(num(e.y, -0.25, 1.25, 0.5)),
    size: r3(num(e.size, SIZE_MIN, SIZE_MAX, 0.4)),
    rot: Math.round(num(e.rot, -180, 180, 0)),
    opacity: r3(num(e.opacity, 0, 1, a.opacity ?? 0.8)),
    ...(hex(e.tint) && a.kind === "vector" ? { tint: hex(e.tint) } : {}),
    ...(e.flipX === true ? { flipX: true } : {}),
    ...(e.flipY === true ? { flipY: true } : {}),
    ...(e.locked === true ? { locked: true } : {}),
    ...(e.hidden === true ? { hidden: true } : {}),
    anim: {
      kind:
        ELEMENT_ANIMS.includes(an.kind) &&
        !(an.kind === "draw" && a.kind !== "vector")
          ? an.kind
          : "none",
      speed: r3(num(an.speed, 0.25, 3, 1)),
      delayMs: Math.round(num(an.delayMs, 0, 60000, 0)),
      durMs: Math.round(
        num(an.durMs, 300, 60000, an.kind === "draw" ? 4000 : 1500),
      ),
    },
  };
}
export function normalizeElements(arr) {
  const out = [],
    seen = new Set();
  for (const [i, e] of (Array.isArray(arr) ? arr : [])
    .slice(0, MAX_ELEMENTS)
    .entries()) {
    const n = normalizeElement(e, i);
    if (!n) continue;
    if (seen.has(n.id)) n.id = `el${i}x`;
    seen.add(n.id);
    out.push(n);
  }
  return out;
}
let seq = 0;
export const newElementId = (existing = []) => {
  const ids = new Set(existing.map((e) => e.id));
  let id;
  do id = `el${Date.now().toString(36).slice(-4)}${(seq++).toString(36)}`;
  while (ids.has(id));
  return id;
};
export function newElement(assetId, existing = [], over = {}) {
  const a = elementById(assetId);
  if (!a) return null;
  return normalizeElement(
    {
      id: newElementId(existing),
      asset: a.id,
      x: 0.5,
      y: 0.82,
      size: a.kind === "raster" ? 0.6 : 0.42,
      opacity: a.opacity,
      anim: { kind: "fade" },
      ...over,
    },
    existing.length,
  );
}

export const POSITION_PRESETS = [
  ["top-left", "Top left", 0.2, 0.12],
  ["top", "Top", 0.5, 0.12],
  ["top-right", "Top right", 0.8, 0.12],
  ["left", "Left", 0.18, 0.5],
  ["center", "Centre", 0.5, 0.5],
  ["right", "Right", 0.82, 0.5],
  ["bottom-left", "Bottom left", 0.2, 0.86],
  ["bottom", "Bottom", 0.5, 0.86],
  ["bottom-right", "Bottom right", 0.8, 0.86],
];

// ---------------------------------------------------------------- deterministic animation
const TAU = Math.PI * 2;
const clamp01 = (v) => Math.max(0, Math.min(1, v));
const ease = (t) => t * t * (3 - 2 * t);
/**
 * Pure: the element's animated state at tMs. { dx, dy } as fractions of the frame, rot in degrees, alpha 0..1 and
 * draw 0..1 (draw-on progress, 1 = complete). still (posters, reduced motion) = the finished, unmoving element.
 */
export function elementStateAt(el, tMs, { still = false } = {}) {
  const s = { dx: 0, dy: 0, rot: 0, alpha: 1, draw: 1 };
  const an = el.anim || { kind: "none" };
  if (still || an.kind === "none") return s;
  const t = Math.max(0, tMs - (an.delayMs || 0)),
    sp = an.speed || 1;
  if (tMs < (an.delayMs || 0) && (an.kind === "fade" || an.kind === "draw"))
    return { ...s, alpha: 0, draw: 0 };
  if (an.kind === "drift") {
    s.dx = Math.sin((TAU * t * sp) / 14000) * 0.018;
    s.dy = Math.sin((TAU * t * sp) / 19000) * 0.008;
  } else if (an.kind === "float") s.dy = Math.sin((TAU * t * sp) / 5000) * 0.01;
  else if (an.kind === "sway") s.rot = Math.sin((TAU * t * sp) / 6000) * 3;
  else if (an.kind === "fade") s.alpha = ease(clamp01(t / an.durMs));
  else if (an.kind === "draw") s.draw = clamp01(t / an.durMs);
  return s;
}

// ---------------------------------------------------------------- loading (same-origin only, bounded cache)
const CACHE_MAX = 40;
const cache = new Map(); // asset id -> { model | img }
const pending = new Map();
const listeners = new Set();
export const onElementsLoaded = (fn) => (
  listeners.add(fn),
  () => listeners.delete(fn)
);
const PATH_OK = /^[MLHVCSQTAZmlhvcsqtaz0-9.,\s eE+-]+$/;
const sameOrigin = (u) =>
  typeof u === "string" &&
  /^\/motion-elements\/[a-z0-9-]+\.(json|webp)$/.test(u);
function touch(id, v) {
  cache.delete(id);
  cache.set(id, v);
  while (cache.size > CACHE_MAX) cache.delete(cache.keys().next().value);
}
export const elementLoaded = (id) => cache.has(id);
/** Validates a vector model fetched from /motion-elements: plain path data and numbers only. */
export function validModel(m) {
  return (
    !!m &&
    m.v === 1 &&
    Array.isArray(m.vb) &&
    m.vb.length === 4 &&
    m.vb.every(Number.isFinite) &&
    Array.isArray(m.shapes) &&
    m.shapes.length > 0 &&
    m.shapes.length < 5000 &&
    m.shapes.every(
      (s) =>
        typeof s.d === "string" && s.d.length < 200000 && PATH_OK.test(s.d),
    ) &&
    Array.isArray(m.order) &&
    m.order.length === m.shapes.length
  );
}
export function loadElement(id) {
  const a = elementById(id);
  if (!a || !sameOrigin(a.file)) return Promise.resolve(false);
  if (cache.has(id)) {
    touch(id, cache.get(id));
    return Promise.resolve(true);
  }
  if (pending.has(id)) return pending.get(id);
  const p = (async () => {
    try {
      if (a.kind === "raster") {
        const img = new Image();
        img.decoding = "async";
        img.src = a.file;
        await img.decode();
        touch(id, { img });
      } else {
        const r = await fetch(a.file, { credentials: "same-origin" });
        const m = r.ok ? await r.json() : null;
        if (!validModel(m)) return false;
        touch(id, { model: m, paths: null });
      }
      listeners.forEach((fn) => fn(id));
      return true;
    } catch {
      return false;
    } finally {
      pending.delete(id);
    }
  })();
  pending.set(id, p);
  return p;
}
/** Every element of a composition, loaded (export awaits this so no frame is drawn without its art). */
export async function loadElements(comp) {
  const ids = [...new Set((comp?.elements || []).map((e) => e.asset))];
  const ok = await Promise.all(ids.map(loadElement));
  return ids.filter((_, i) => !ok[i]);
}
/** Test hook: inject a model (node tests have no fetch of /public). */
export const _setElementModel = (id, model) =>
  touch(id, { model, paths: null });

// ---------------------------------------------------------------- painting
export const DEFAULT_INK = "#2a2622";
const pathsOf = (entry) =>
  entry.paths || (entry.paths = entry.model.shapes.map((s) => new Path2D(s.d)));

/** Box of an element in a W×H frame (centre cx/cy, width w, height h), before animation. */
export function elementBox(el, W, H) {
  const a = elementById(el.asset);
  const w = el.size * W,
    h = w / (a?.aspect || 1);
  return { cx: el.x * W, cy: el.y * H, w, h };
}

/**
 * Paints comp.elements (bottom -> top). Returns the number drawn (callers reset text state when > 0).
 * ink: the colour for `currentColor` when an element has no tint (the poem's text colour keeps contrast on dark looks).
 */
export function paintElements(ctx, comp, W, H, tMs, { still = false } = {}) {
  const list = comp?.elements;
  if (!list?.length || typeof Path2D === "undefined") return 0;
  const ink = comp.style?.color || DEFAULT_INK;
  let n = 0;
  for (const el of list) {
    if (el.hidden) continue;
    const entry = cache.get(el.asset);
    if (!entry) continue;
    const st = elementStateAt(el, tMs, { still });
    const alpha = el.opacity * st.alpha;
    if (alpha <= 0.001 || st.draw <= 0) continue;
    const b = elementBox(el, W, H);
    ctx.save();
    ctx.translate(b.cx + st.dx * W, b.cy + st.dy * H);
    if (el.rot || st.rot) {
      // sway pivots on the element's base, a still rotation on its centre
      if (st.rot) {
        ctx.translate(0, b.h / 2);
        ctx.rotate(((el.rot + st.rot) * Math.PI) / 180);
        ctx.translate(0, -b.h / 2);
      } else ctx.rotate((el.rot * Math.PI) / 180);
    }
    ctx.scale(el.flipX ? -1 : 1, el.flipY ? -1 : 1);
    if (entry.img) {
      ctx.globalAlpha = alpha;
      ctx.drawImage(entry.img, -b.w / 2, -b.h / 2, b.w, b.h);
    } else drawVector(ctx, entry, b, el.tint || ink, alpha, st.draw);
    ctx.restore();
    n++;
  }
  return n;
}

/** Draw-on: strokes (and filled shapes' outlines) are traced in draw order over the first 75%; fills reveal after. */
function drawVector(ctx, entry, b, color, alpha, draw) {
  const m = entry.model,
    [vx, vy, vw, vh] = m.vb,
    k = b.w / vw;
  const paths = pathsOf(entry);
  ctx.scale(k, b.h / vh);
  ctx.translate(-vx - vw / 2, -vy - vh / 2);
  const col = (p) => (p === 1 ? color : p);
  const lineP = draw >= 1 ? 1 : Math.min(1, draw / 0.75),
    fillP = draw >= 1 ? 1 : ease(clamp01((draw - 0.7) / 0.3));
  let budget = Infinity;
  if (lineP < 1)
    budget = lineP * m.order.reduce((t, i) => t + (m.shapes[i].len || 0), 0);
  for (const i of m.order) {
    const s = m.shapes[i],
      p = paths[i];
    const so = alpha * (s.o ?? 1);
    if (s.m) {
      ctx.save();
      ctx.transform(...s.m);
    }
    if (s.f && fillP > 0) {
      ctx.globalAlpha = so * (s.fo ?? 1) * fillP;
      ctx.fillStyle = col(s.f);
      ctx.fill(p);
    }
    const strokeIt = s.s || lineP < 1 || fillP < 1;
    if (strokeIt && budget > 0) {
      const drawn = Math.min(s.len || 0, budget);
      ctx.globalAlpha = so * (s.s ? (s.so ?? 1) : 0.85 * (1 - fillP));
      if (ctx.globalAlpha > 0.001) {
        ctx.strokeStyle = col(s.s || s.f);
        ctx.lineWidth = s.s ? s.w : Math.max(1.5, vw / 500);
        ctx.lineCap = s.cap || "butt";
        ctx.lineJoin = s.join || "miter";
        if (lineP < 1) ctx.setLineDash([drawn, (s.len || 0) + 1]);
        else ctx.setLineDash(s.dash || []);
        ctx.stroke(p);
      }
    }
    if (lineP < 1) budget -= s.len || 0;
    if (s.m) ctx.restore();
  }
  ctx.setLineDash([]);
}

