export const DECORATION_KEYS = Object.keys(DECORATION_PRESETS);
export function decorationElements(key) {
  const out = [];
  for (const it of DECORATION_PRESETS[key]?.items || []) {
    const e = newElement(it.asset, out, it);
    if (e) out.push(e);
  }
  return out;
}
