/**
 * Plain-language warnings for the current frame: an opaque element over the poem, or one mostly outside the frame
 * (typically after switching to a shorter format). Positions are relative, so formats adapt automatically.
 */
export function elementWarnings(comp, W, H, textRect) {
  const out = [];
  for (const el of comp?.elements || []) {
    if (el.hidden) continue;
    const a = elementById(el.asset),
      b = elementBox(el, W, H);
    const x0 = b.cx - b.w / 2,
      y0 = b.cy - b.h / 2,
      x1 = x0 + b.w,
      y1 = y0 + b.h;
    const vis =
      Math.max(0, Math.min(W, x1) - Math.max(0, x0)) *
      Math.max(0, Math.min(H, y1) - Math.max(0, y0));
    if (vis < 0.4 * b.w * b.h)
      out.push(`"${a.name}" is mostly outside the frame.`);
    if (textRect && el.opacity > 0.5) {
      const ox = Math.max(
        0,
        Math.min(x1, textRect.x + textRect.w) - Math.max(x0, textRect.x),
      );
      const oy = Math.max(
        0,
        Math.min(y1, textRect.y + textRect.h) - Math.max(y0, textRect.y),
      );
      if (ox * oy > 0.25 * textRect.w * textRect.h)
        out.push(
          `"${a.name}" covers much of the poem: lower its opacity or move it.`,
        );
    }
  }
  return out;
}
